#!/usr/bin/env python3
"""Run chapter 00 in independent directories on native x86-64 Linux."""
import os, platform, subprocess, tempfile
from pathlib import Path
assert platform.system() == 'Linux' and platform.machine() == 'x86_64'
root=Path(tempfile.mkdtemp(prefix='linker-ch03.'))
print('WORKDIR='+str(root),flush=True)
def case(name, files, commands):
 d=root/name;d.mkdir()
 for filename,source in files.items():(d/filename).write_text(source)
 for cmd in commands:
  print('\n$ '+cmd,flush=True)
  p=subprocess.run(['bash','-c','ulimit -c 0; '+cmd],cwd=d,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
  print(p.stdout,end='',flush=True);print('status='+str(p.returncode),flush=True)
case('weak', {'a.c': 'int counter=1; int main(void){return counter;}', 'b.c': 'int counter=2;', 'w.c': '__attribute__((weak)) int counter=3;', 'w2.c': '__attribute__((weak)) int counter=4;', 'm.c': 'extern int counter;int main(void){return counter;}', 'u.c': '// u.c\nextern void hook(void) __attribute__((weak));\nint main(void) { if (hook) hook(); return 0; }\n', 'wk.s': '.text\n.globl main\n.weak hook\nmain: mov hook@GOTPCREL(%rip), %rax\nret\n', 'sk.s': '.globl hook\n'}, ['clang -O1 -c a.c b.c w.c w2.c m.c u.c wk.s sk.s', 'ld -e main a.o b.o', 'ld.lld -e main a.o b.o', 'nm w.o a.o', 'ld -e main w.o a.o -o s2; nm s2 | grep counter; llvm-objdump -s -j .data s2', 'ld -e main m.o w.o w2.o -o s3; llvm-objdump -s -j .data s3', 'ld -e main m.o w2.o w.o -o s4; llvm-objdump -s -j .data s4', 'ld -e main u.o -o s6; llvm-objdump -d --no-show-raw-insn s6; llvm-objdump -s -j .got s6', 'ld -e main wk.o sk.o', 'ld.lld -e main wk.o sk.o', 'ld -e main m.o b.o w.o -y counter', 'ld -e main a.o b.o --allow-multiple-definition -o dup; nm dup | grep counter'])
